You are implementing a shipment tracking Blazor Web App. The project is already scaffolded at `/tmp/sv-8e39891f4e86476f8259a50f28947d22/ShipmentTracker/` with Interactive Auto, Global mode and Individual authentication.

The project structure:
- `ShipmentTracker/` (server project)
- `ShipmentTracker.Client/` (client/WebAssembly project)

## What to implement

### 1. Shared Models (in Client project since interactive components need them)

Create `ShipmentTracker.Client/Models/Shipment.cs`:
```csharp
namespace ShipmentTracker.Client.Models;

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Cancelled
}

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}
```

### 2. Service Interface (Client project)

Create `ShipmentTracker.Client/Services/IShipmentService.cs`:
```csharp
namespace ShipmentTracker.Client.Services;

using ShipmentTracker.Client.Models;

public interface IShipmentService
{
    Task<List<Shipment>> GetAllShipmentsAsync();
    Task<Shipment?> GetByTrackingNumberAsync(string trackingNumber);
    Task<Shipment?> UpdateStatusAsync(int id, ShipmentStatus newStatus);
}
```

### 3. Client-side Implementation (Client project)

Create `ShipmentTracker.Client/Services/ShipmentHttpService.cs`:
```csharp
using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class ShipmentHttpService : IShipmentService
{
    private readonly HttpClient _http;

    public ShipmentHttpService(HttpClient http)
    {
        _http = http;
    }

    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await _http.GetFromJsonAsync<List<Shipment>>("api/shipments") ?? [];
    }

    public async Task<Shipment?> GetByTrackingNumberAsync(string trackingNumber)
    {
        var response = await _http.GetAsync($"api/shipments/track/{trackingNumber}");
        if (!response.IsSuccessStatusCode) return null;
        return await response.Content.ReadFromJsonAsync<Shipment>();
    }

    public async Task<Shipment?> UpdateStatusAsync(int id, ShipmentStatus newStatus)
    {
        var response = await _http.PutAsJsonAsync($"api/shipments/{id}/status", newStatus);
        if (!response.IsSuccessStatusCode) return null;
        return await response.Content.ReadFromJsonAsync<Shipment>();
    }
}
```

### 4. Register HttpClient and service in Client Program.cs

Edit `ShipmentTracker.Client/Program.cs` to:
```csharp
using Microsoft.AspNetCore.Components.WebAssembly.Hosting;
using ShipmentTracker.Client.Services;

var builder = WebAssemblyHostBuilder.CreateDefault(args);

builder.Services.AddAuthorizationCore();
builder.Services.AddCascadingAuthenticationState();
builder.Services.AddAuthenticationStateDeserialization();

builder.Services.AddScoped(sp => new HttpClient { BaseAddress = new Uri(builder.HostEnvironment.BaseAddress) });
builder.Services.AddScoped<IShipmentService, ShipmentHttpService>();

await builder.Build().RunAsync();
```

### 5. Server-side Service Implementation

Create `ShipmentTracker/Services/ShipmentServerService.cs`:
```csharp
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Services;

public class ShipmentServerService : IShipmentService
{
    private static readonly List<Shipment> _shipments = new()
    {
        new Shipment { Id = 1, TrackingNumber = "TRK-1001", Origin = "New York, USA", Destination = "London, UK", Status = ShipmentStatus.InTransit, ShippedDate = DateTime.UtcNow.AddDays(-3), EstimatedDelivery = DateTime.UtcNow.AddDays(4), CustomerEmail = "alice@example.com", Description = "Electronics - Laptop" },
        new Shipment { Id = 2, TrackingNumber = "TRK-1002", Origin = "Shanghai, China", Destination = "Los Angeles, USA", Status = ShipmentStatus.PickedUp, ShippedDate = DateTime.UtcNow.AddDays(-1), EstimatedDelivery = DateTime.UtcNow.AddDays(10), CustomerEmail = "bob@example.com", Description = "Furniture - Office Desk" },
        new Shipment { Id = 3, TrackingNumber = "TRK-1003", Origin = "Berlin, Germany", Destination = "Tokyo, Japan", Status = ShipmentStatus.OutForDelivery, ShippedDate = DateTime.UtcNow.AddDays(-7), EstimatedDelivery = DateTime.UtcNow, CustomerEmail = "carol@example.com", Description = "Medical Supplies" },
        new Shipment { Id = 4, TrackingNumber = "TRK-1004", Origin = "São Paulo, Brazil", Destination = "Sydney, Australia", Status = ShipmentStatus.Pending, ShippedDate = DateTime.UtcNow, EstimatedDelivery = DateTime.UtcNow.AddDays(14), CustomerEmail = "dave@example.com", Description = "Auto Parts" },
        new Shipment { Id = 5, TrackingNumber = "TRK-1005", Origin = "Mumbai, India", Destination = "Dubai, UAE", Status = ShipmentStatus.Delivered, ShippedDate = DateTime.UtcNow.AddDays(-10), EstimatedDelivery = DateTime.UtcNow.AddDays(-2), CustomerEmail = "eve@example.com", Description = "Textiles" },
    };

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return Task.FromResult(_shipments.ToList());
    }

    public Task<Shipment?> GetByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = _shipments.FirstOrDefault(s => s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
        return Task.FromResult(shipment);
    }

    public Task<Shipment?> UpdateStatusAsync(int id, ShipmentStatus newStatus)
    {
        var shipment = _shipments.FirstOrDefault(s => s.Id == id);
        if (shipment is null) return Task.FromResult<Shipment?>(null);
        shipment.Status = newStatus;
        return Task.FromResult<Shipment?>(shipment);
    }
}
```

### 6. API Endpoints and Server DI Registration

In `ShipmentTracker/Program.cs`, add these BEFORE `app.Run()`:
- Register the service: `builder.Services.AddScoped<IShipmentService, ShipmentServerService>();` (after the Identity service registrations, before `var app = builder.Build();`)
- Also register HttpClient for server-side prerendering: `builder.Services.AddScoped(sp => new HttpClient { BaseAddress = new Uri("http://localhost:5000") });`
- Add API endpoints before `app.Run();`:

```csharp
// Shipment API endpoints
app.MapGet("api/shipments", async (IShipmentService service) =>
    Results.Ok(await service.GetAllShipmentsAsync()))
    .RequireAuthorization();

app.MapGet("api/shipments/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
{
    var shipment = await service.GetByTrackingNumberAsync(trackingNumber);
    return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
});

app.MapPut("api/shipments/{id}/status", async (int id, ShipmentStatus newStatus, IShipmentService service) =>
{
    var shipment = await service.UpdateStatusAsync(id, newStatus);
    return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
}).RequireAuthorization();
```

You need to add `using ShipmentTracker.Client.Services;` and `using ShipmentTracker.Services;` and `using ShipmentTracker.Client.Models;` to the top of server Program.cs.

