            (string.IsNullOrEmpty(statusFilter) || s.Status.ToString() == statusFilter));

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task UpdateStatus(int id, ChangeEventArgs e)
    {
        if (e.Value is string val && Enum.TryParse<ShipmentStatus>(val, out var newStatus))
        {
            await ShipmentService.UpdateStatusAsync(id, newStatus);
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
    }

